import{_ as o,C as s,o as n,c as i,j as a,a as r,E as p,a3 as d}from"./chunks/framework.DEy3KOfk.js";const k=JSON.parse('{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/docs/index.md"},"headers":[],"relativePath":"packages/waypoints/docs/index.md","filePath":"packages/waypoints/docs/index.md","lastUpdated":1791464787000}'),c={name:"packages/waypoints/docs/index.md"},l={id:"waypoints",tabindex:"-1",class:"component-page-title"},h={class:"component-page-title__version"};function m(y,e,u,g,w,v){const t=s("Badge");return n(),i("div",null,[a("h1",l,[e[0]||(e[0]=a("img",{class:"component-page-title__icon",src:"/pumpkin-plugins/packages/waypoints/icon.svg",alt:"","aria-hidden":"true",width:"48",height:"48"},null,-1)),e[1]||(e[1]=a("span",{class:"component-page-title__text"},[r("Waypoints "),a("a",{class:"header-anchor",href:"#waypoints","aria-label":'Permalink to "Waypoints"'},"​")],-1)),a("span",h,[p(t,{type:"info",text:"v0.0.0"})])]),e[2]||(e[2]=d('<p>Waypoints stores shared named positions on the server. Waypoints are restricted by default; an operator can make one public or grant access to players, permission nodes, or permission-marker groups. Records have no creator ownership.</p><p>Install <code>waypoints.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart. The plugin has no config file. It stores versioned records in <code>plugins/data/Waypoints/waypoints.json</code> and keeps a byte-identical <code>waypoints.v1.json</code> backup when migrating the previous schema.</p><h2 id="create-and-use-waypoints" tabindex="-1">Create and use waypoints <a class="header-anchor" href="#create-and-use-waypoints" aria-label="Permalink to &quot;Create and use waypoints&quot;">​</a></h2><p>Operators can create a waypoint at their exact position with <code>/wp create &quot;Home Base&quot;</code>, or provide absolute coordinates with <code>/wp create &quot;Home Base&quot; 120.5 64 -30</code>. Names are unique across dimensions. Use <code>/wp list</code> to see enabled waypoints you can access, <code>/wp info &lt;name&gt;</code> for details, and <code>/wp tp &lt;name&gt;</code> to teleport yourself. Operators can use <code>/wp tp &lt;name&gt; @a</code> to teleport a player selector.</p><p>Only server operators can create, edit, enable, disable, grant, or delete waypoints. Every administrative handler checks Pumpkin&#39;s operator list even if a command permission was manually granted. Player grants resolve online names and store UUIDs. A group grant checks the permission marker <code>Waypoints:group.&lt;slug&gt;</code>; another permission provider must assign that marker to group members.</p><h2 id="java-waypoint-hud" tabindex="-1">Java waypoint HUD <a class="header-anchor" href="#java-waypoint-hud" aria-label="Permalink to &quot;Java waypoint HUD&quot;">​</a></h2><p>Minecraft Java 26.3 players see each enabled waypoint they can access in the same dimension and within its optional visibility range. The display shows the waypoint label (or name) in its color and the rounded distance in meters. Each player&#39;s display packets are private to that player, so restricted names and personalized distances are not sent to other clients.</p><p>The HUD uses client-only TextDisplay packets on a camera-relative plane about three blocks ahead, updated once per server tick. Within ten blocks, each label eases into a world position two blocks above its waypoint and stays anchored there within three blocks. Labels render through world geometry so terrain does not hide them. Screen direction is eased to reduce movement jitter; ordinary waypoints use stronger vertical stabilization, while destinations several blocks above or below the player follow height changes faster. Small stationary camera-position and yaw changes are also ignored. Other Java protocol versions and Bedrock clients do not receive the HUD. The stored item icon is not displayed yet.</p><p>Malformed or unsupported storage is preserved and disables writes. Fix the file before expecting changes to persist.</p>',9))])}const _=o(c,[["render",m]]);export{k as __pageData,_ as default};
